Here is the commit message:
fix IPv6 parse error introduced in
 7bf3e12c30d0585743792982ed8bcfc44aecae34

Here is the root cause:
The bug was caused by incorrect memory management in the `resolve_split_name` function, where the original pointer for the host string was being freed instead of the allocated memory for the new host string. This could lead to memory leaks or undefined behavior when parsing IPv6 addresses, particularly when brackets are involved. The change ensures that the correct pointer is freed, preventing these issues.

Here is the patch:
  */
 int resolve_split_name(struct addrinfo **out, const char* ct_host, const char* serv)
 {
    struct addrinfo hint;
    char *end;
    int res;
-   char* host;
+   char* host, *host_base;

    memset(&hint, 0, sizeof(hint));
    hint.ai_family = PF_UNSPEC;
    hint.ai_socktype = SOCK_STREAM;

    /* Copy parameter so not to clobber data in libconfig */
-   res = asprintf(&host, "%s", ct_host);
+   res = asprintf(&host_base, "%s", ct_host);
    if (res == -1) {
        log_message(LOG_ERR, "asprintf: cannot allocate memory");
        return -1;
    }

+   host = host_base;
+
    /* If it is a RFC-Compliant IPv6 address ("[1234::12]:443"), remove brackets
     * around IP address */
    if (host[0] == '[') {
        end = strrchr(host, ']');
        if (!end) {
            fprintf(stderr, "%s: no closing bracket in IPv6 address?\n", host);
        }
        host++; /* skip first bracket */
        *end = 0; /* remove last bracket */
    }

    res = getaddrinfo(host, serv, &hint, out);
    if (res)
       log_message(LOG_ERR, "%s `%s:%s'\n", gai_strerror(res), host, serv);
-   free(host);
+   free(host_base);
    return res;
 }



